Path("frontend/lib/features/journal/widgets/insulin_logging.dart").write_text('''double? parseTakenInsulinUnits(String raw) {\n  final normalized = raw.trim().replaceAll(',', '.');\n  if (normalized.isEmpty) return null;\n  final value = double.tryParse(normalized);\n  if (value == null || !value.isFinite || value <= 0) return null;\n  return value;\n}\n\nbool isValidTakenInsulinInput(String raw) {\n  if (raw.trim().isEmpty) return true;\n  return parseTakenInsulinUnits(raw) != null;\n}\n\nString formatTakenInsulinUnits(double value) {\n  final fixed = value.toStringAsFixed(2);\n  return fixed.replaceFirst(RegExp(r'\\.?0+$'), '');\n}\n''')

