translations = {
    "fr": {
        "journalEditTitle": "Modifier la mesure",
        "journalEditSubtitle": "Corrige uniquement les faits réellement enregistrés.",
        "journalEditContextPreserved": "Le repas, le contexte glycémique, l’heure et les autres détails restent inchangés dans cet écran.",
        "journalNoInsulinTakenHint": "Laisse vide si aucune insuline n’a été prise pour cette entrée.",
        "journalUpdated": "Mesure mise à jour.",
    },
    "en": {
        "journalEditTitle": "Edit measurement",
        "journalEditSubtitle": "Correct only the facts that were actually recorded.",
        "journalEditContextPreserved": "Meal, glucose context, time and other details stay unchanged on this screen.",
        "journalNoInsulinTakenHint": "Leave blank if no insulin was taken for this entry.",
        "journalUpdated": "Measurement updated.",
    },
    "ar": {
        "journalEditTitle": "تعديل القياس",
        "journalEditSubtitle": "صحّح فقط المعلومات التي تم تسجيلها فعلاً.",
        "journalEditContextPreserved": "يبقى الطعام وسياق قياس السكر والوقت وباقي التفاصيل دون تغيير في هذه الشاشة.",
        "journalNoInsulinTakenHint": "اترك الحقل فارغاً إذا لم يتم أخذ إنسولين لهذا التسجيل.",
        "journalUpdated": "تم تحديث القياس.",
    },
}
for locale, values in translations.items():
    path = Path(f"frontend/lib/l10n/app_{locale}.arb")
    text = path.read_text()
    marker = '  "journalInvalidGlucose":'
    if text.count(marker) != 1:
        raise SystemExit(f"{path}: journalInvalidGlucose marker missing/ambiguous")
    block = ''.join(f'  "{key}": "{value}",\n' for key, value in values.items())
    path.write_text(text.replace(marker, block + marker, 1))

