Path("frontend/test/features/insulin_logging_v2_test.dart").write_text('''import 'package:amina/data/drift/database.dart';\nimport 'package:amina/features/dashboard/widgets/add_log_sheet.dart';\nimport 'package:amina/features/journal/edit_log_screen.dart';\nimport 'package:amina/features/journal/widgets/insulin_logging.dart';\nimport 'package:amina/l10n/app_localizations.dart';\nimport 'package:drift/drift.dart' as drift;\nimport 'package:drift/native.dart';\nimport 'package:flutter/material.dart';\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:provider/provider.dart';\n\nAppDatabase _db() => AppDatabase(NativeDatabase.memory());\n\nWidget _providers(AppDatabase db, Widget child, {Locale locale = const Locale('fr')}) {\n  return MaterialApp(\n    locale: locale,\n    localizationsDelegates: AppLocalizations.localizationsDelegates,\n    supportedLocales: AppLocalizations.supportedLocales,\n    home: Scaffold(\n      body: MultiProvider(\n        providers: <SingleChildWidget>[\n          Provider<AppDatabase>.value(value: db),\n          Provider<PatientProfileData?>.value(value: null),\n        ],\n        child: child,\n      ),\n    ),\n  );\n}\n\nvoid main() {\n  test('dose formatter preserves patient-entered decimal precision', () {\n    expect(formatTakenInsulinUnits(4), '4');\n    expect(formatTakenInsulinUnits(4.5), '4.5');\n    expect(formatTakenInsulinUnits(4.75), '4.75');\n    expect(isValidTakenInsulinInput(''), isTrue);\n    expect(isValidTakenInsulinInput('4,5'), isTrue);\n    expect(isValidTakenInsulinInput('0'), isFalse);\n    expect(isValidTakenInsulinInput('-1'), isFalse);\n  });\n\n  testWidgets('add log persists an actual decimal dose and never offers presets', (tester) async {\n    final db = _db();\n    addTearDown(db.close);\n    tester.view.physicalSize = const Size(1440, 1000);\n    tester.view.devicePixelRatio = 1;\n    addTearDown(tester.view.resetPhysicalSize);\n\n    await tester.pumpWidget(_providers(db, const AddLogSheet()));\n    await tester.pumpAndSettle();\n    await tester.enterText(find.byKey(const Key('glucose-input')), '126');\n    await tester.enterText(find.byKey(const Key('insulin-taken-input')), '4,5');\n    expect(find.textContaining('Dose standard'), findsNothing);\n    expect(find.textContaining('Dose critique'), findsNothing);\n    await tester.tap(find.text('Enregistrer la mesure'));\n    await tester.pumpAndSettle();\n\n    final logs = await db.select(db.logEntries).get();\n    expect(logs, hasLength(1));\n    expect(logs.single.insulinUnits, 4.5);\n  });\n\n  testWidgets('zero is not persisted as an administered insulin dose', (tester) async {\n    final db = _db();\n    addTearDown(db.close);\n    tester.view.physicalSize = const Size(1440, 1000);\n    tester.view.devicePixelRatio = 1;\n    addTearDown(tester.view.resetPhysicalSize);\n\n    await tester.pumpWidget(_providers(db, const AddLogSheet()));\n    await tester.pumpAndSettle();\n    await tester.enterText(find.byKey(const Key('glucose-input')), '126');\n    await tester.enterText(find.byKey(const Key('insulin-taken-input')), '0');\n    await tester.tap(find.text('Enregistrer la mesure'));\n    await tester.pumpAndSettle();\n    expect(await db.select(db.logEntries).get(), isEmpty);\n    expect(find.text('La dose d’insuline saisie n’est pas valide.'), findsOneWidget);\n  });\n\n  testWidgets('edit clears insulin without rewriting meal context or Ramadan legacy state', (tester) async {\n    final db = _db();\n    addTearDown(db.close);\n    final id = await db.into(db.logEntries).insert(\n      LogEntriesCompanion.insert(\n        createdAt: DateTime(2026, 8, 9, 12),\n        bloodSugar: 130,\n        insulinUnits: const drift.Value(4.5),\n        glycemicContext: const drift.Value('post_meal'),\n        mealType: const drift.Value('lunch'),\n        clientUuid: '11111111-1111-1111-1111-111111111111',\n        loggedAt: drift.Value(DateTime(2026, 8, 9, 12)),\n        ramadanMode: const drift.Value(true),\n        syncStatus: const drift.Value('synced'),\n        syncAttempts: const drift.Value(2),\n        errorSync: const drift.Value(true),\n      ),\n    );\n\n    await tester.pumpWidget(_providers(db, EditLogScreen(logId: id)));\n    await tester.pumpAndSettle();\n    final insulinField = tester.widget<TextField>(find.byKey(const Key('edit-insulin-taken-input')));\n    expect(insulinField.controller?.text, '4.5');\n    expect(find.text('Mode Ramadan'), findsNothing);\n    expect(find.text('Iftar'), findsNothing);\n\n    await tester.enterText(find.byKey(const Key('edit-insulin-taken-input')), '');\n    await tester.tap(find.byKey(const Key('save-edit-log-button')));\n    await tester.pumpAndSettle();\n\n    final log = await db.getLogById(id);\n    expect(log!.insulinUnits, isNull);\n    expect(log.glycemicContext, 'post_meal');\n    expect(log.mealType, 'lunch');\n    expect(log.ramadanMode, isTrue);\n    expect(log.syncStatus, 'pending');\n    expect(log.syncAttempts, 0);\n    expect(log.errorSync, isFalse);\n  });\n\n  testWidgets('edit accepts decimal administered dose without stepper rounding', (tester) async {\n    final db = _db();\n    addTearDown(db.close);\n    final id = await db.into(db.logEntries).insert(\n      LogEntriesCompanion.insert(\n        createdAt: DateTime(2026, 8, 9, 12),\n        bloodSugar: 130,\n        clientUuid: '22222222-2222-2222-2222-222222222222',\n      ),\n    );\n    await tester.pumpWidget(_providers(db, EditLogScreen(logId: id)));\n    await tester.pumpAndSettle();\n    await tester.enterText(find.byKey(const Key('edit-insulin-taken-input')), '4.75');\n    await tester.tap(find.byKey(const Key('save-edit-log-button')));\n    await tester.pumpAndSettle();\n    expect((await db.getLogById(id))!.insulinUnits, 4.75);\n  });\n\n  testWidgets('edit flow is localized in Arabic RTL', (tester) async {\n    final db = _db();\n    addTearDown(db.close);\n    final id = await db.into(db.logEntries).insert(\n      LogEntriesCompanion.insert(\n        createdAt: DateTime(2026, 8, 9, 12),\n        bloodSugar: 130,\n        clientUuid: '33333333-3333-3333-3333-333333333333',\n      ),\n    );\n    await tester.pumpWidget(_providers(db, EditLogScreen(logId: id), locale: const Locale('ar')));\n    await tester.pumpAndSettle();\n    expect(find.text('تعديل القياس'), findsOneWidget);\n    expect(find.text('Modifier la mesure'), findsNothing);\n    expect(Directionality.of(tester.element(find.text('تعديل القياس'))), TextDirection.rtl);\n  });\n}\n''')
